1	import {MongoSessionStore} from './mongoSessionStore.js';
2	import type {CollectionLike} from './mongoDriverTypes.js';
3	import type {MongoSessionDocument} from './mongoSessionDocument.js';
4	
5	// A store that caches before it writes keeps what it failed to save, credentials and all, until the process ends.
6	
7	const refusingCollection = (): CollectionLike<MongoSessionDocument> =>
8	  ({
9	    findOne: () => Promise.resolve(null),
10	    updateOne: () => Promise.reject(new Error('database unreachable')),
11	    deleteOne: () => Promise.resolve({deletedCount: 0}),
12	    deleteMany: () => Promise.resolve({deletedCount: 0}),
13	    countDocuments: () => Promise.resolve(0),
14	  }) as CollectionLike<MongoSessionDocument>;
15	
16	const outcomeOf = (call: Promise<unknown>): Promise<string> =>
17	  call.then(() => 'resolved').catch((error: Error) => error.message);
